from typing import List, Optional

def get_lucky_numbers_count_up_to(n: int, target_sum: int) -> int:
    """
    Counts how many numbers <= n have a digit sum equal to target_sum.
    Uses digit DP to count numbers with digit sum S in range [0, n].
    """
    s_n = str(n)
    length = len(s_n)
    memo = {}

    def dp(idx: int, current_sum: int, is_less: bool) -> int:
        if current_sum > target_sum:
            return 0
        if idx == length:
            return 1 if current_sum == target_sum else 0

        state = (idx, current_sum, is_less)
        if state in memo:
            return memo[state]

        limit = int(s_n[idx]) if not is_less else 9
        count = 0
        for digit in range(limit + 1):
            count += dp(idx + 1, current_sum + digit, is_less or (digit < limit))

        memo[state] = count
        return count

    return dp(0, 0, False)

def find_nth_lucky_number(n: int, target_sum: int) -> int:
    """
    Finds the n-th smallest number with digit sum equal to target_sum.
    Uses binary search over the range of possible numbers.
    """
    low = 1
    high = 10**(target_sum + 1)
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if get_lucky_numbers_count_up_to(mid, target_sum) >= n:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

def solve_math_problem(an: int, target_sum: int, multiplier: int) -> int:
    """
    Given an = a_n, finds a_{multiplier * n}.
    """
    n = get_lucky_numbers_count_up_to(an, target_sum)
    return find_nth_lucky_number(n * multiplier, target_sum)

